[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Leap Studio — Your Reinvention and Experience Partner</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet">
<style>
/* ===== CSS CUSTOM PROPERTIES (OKLCH) ===== */
:root {
  --bg-primary: oklch(4% 0.01 260);
  --bg-surface: oklch(10% 0.01 260);
  --bg-surface-hover: oklch(15% 0.01 260);
  --bg-elevated: oklch(14% 0.01 260);
  --text-primary: oklch(96% 0 0);
  --text-secondary: oklch(72% 0.02 260);
  --text-muted: oklch(50% 0.02 260);
  --accent: oklch(65% 0.22 260);
  --accent-glow: oklch(65% 0.22 260 / 0.3);
  --accent-warm: oklch(72% 0.14 55);
  --border: oklch(22% 0.02 260);
  --border-light: oklch(18% 0.01 260);
  --space-xs: 0.5rem;
  --space-sm: 1rem;
  --space-md: 1.5rem;
  --space-lg: 2.5rem;
  --space-xl: 4rem;
  --space-2xl: 6rem;
  --space-3xl: 8rem;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-xl: 28px;
  --font-xs: 0.75rem;
  --font-sm: 0.875rem;
  --font-base: 1rem;
  --font-lg: 1.125rem;
  --font-xl: 1.25rem;
  --font-2xl: 1.5rem;
  --font-3xl: 2rem;
  --font-4xl: 2.75rem;
  --font-5xl: 3.75rem;
  --font-6xl: 5rem;
  --transition-fast: 150ms ease;
  --transition-base: 300ms ease;
  --transition-slow: 500ms cubic-bezier(0.4, 0, 0.2, 1);
  --max-width: 1400px;
}

/* ===== RESET ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; font-size: 16px; }
body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; font: inherit; border: none; background: none; color: inherit; }
ul { list-style: none; }

/* ===== UTILITY ===== */
.container { width: 100%; max-width: var(--max-width); margin: 0 auto; padding: 0 var(--space-lg); }
.section { padding: var(--space-3xl) 0; }
.section-label {
  font-size: var(--font-sm);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--accent);
  margin-bottom: var(--space-sm);
}
.section-title {
  font-size: var(--font-4xl);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.02em;
  margin-bottom: var(--space-md);
}
.section-subtitle {
  font-size: var(--font-lg);
  color: var(--text-secondary);
  max-width: 680px;
  line-height: 1.7;
}
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.85rem 1.75rem;
  font-size: var(--font-sm);
  font-weight: 600;
  border-radius: 100px;
  transition: all var(--transition-base);
  white-space: nowrap;
}
.btn-primary {
  background: var(--text-primary);
  color: var(--bg-primary);
}
.btn-primary:hover { background: oklch(88% 0 0); transform: translateY(-1px); }
.btn-outline {
  border: 1px solid var(--border);
  color: var(--text-primary);
}
.btn-outline:hover { border-color: var(--text-primary); background: oklch(100% 0 0 / 0.05); }
.btn-accent {
  background: var(--accent);
  color: #fff;
}
.btn-accent:hover { background: oklch(60% 0.22 260); transform: translateY(-1px); }

/* ===== NAVIGATION ===== */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  padding: 1.25rem 0;
  transition: background var(--transition-base), backdrop-filter var(--transition-base);
}
.nav.scrolled {
  background: oklch(4% 0.01 260 / 0.85);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--border-light);
}
.nav .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.nav-logo {
  font-size: var(--font-2xl);
  font-weight: 900;
  letter-spacing: -0.03em;
  color: var(--text-primary);
}
.nav-logo span { color: var(--accent); }
.nav-links {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
}
.nav-links a {
  font-size: var(--font-sm);
  font-weight: 500;
  color: var(--text-secondary);
  transition: color var(--transition-fast);
  position: relative;
}
.nav-links a:hover, .nav-links a.active { color: var(--text-primary); }
.nav-links a::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--accent);
  transition: width var(--transition-base);
}
.nav-links a:hover::after { width: 100%; }

/* Language Selector */
.lang-selector {
  position: relative;
}
.lang-toggle {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.5rem 0.75rem;
  border: 1px solid var(--border);
  border-radius: 100px;
  font-size: var(--font-xs);
  font-weight: 600;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
}
.lang-toggle:hover { border-color: var(--text-secondary); color: var(--text-primary); }
.lang-toggle svg { width: 14px; height: 14px; opacity: 0.6; }
.lang-dropdown {
  position: absolute;
  top: calc(100% + 0.5rem);
  right: 0;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 0.5rem;
  min-width: 200px;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: all var(--transition-base);
  box-shadow: 0 20px 40px oklch(0% 0 0 / 0.5);
}
.lang-dropdown.open { opacity: 1; visibility: visible; transform: translateY(0); }
.lang-dropdown button {
  display: block;
  width: 100%;
  text-align: left;
  padding: 0.6rem 1rem;
  font-size: var(--font-sm);
  font-weight: 500;
  border-radius: var(--radius-sm);
  transition: background var(--transition-fast);
}
.lang-dropdown button:hover { background: var(--bg-surface-hover); }
.lang-dropdown button.active { color: var(--accent); font-weight: 600; }

/* Mobile Nav Toggle */
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 0.5rem;
}
.nav-toggle span {
  width: 24px;
  height: 2px;
  background: var(--text-primary);
  transition: all var(--transition-base);
  transform-origin: center;
}
.nav-toggle.open span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.nav-toggle.open span:nth-child(2) { opacity: 0; }
.nav-toggle.open span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

/* Mobile Nav */
.mobile-nav {
  position: fixed;
  top: 0;
  right: -100%;
  width: 100%;
  max-width: 400px;
  height: 100vh;
  background: var(--bg-surface);
  padding: 6rem var(--space-lg) var(--space-lg);
  transition: right var(--transition-slow);
  z-index: 999;
  display: flex;
  flex-direction: column;
  gap: var(--space-lg);
}
.mobile-nav.open { right: 0; }
.mobile-nav a {
  font-size: var(--font-xl);
  font-weight: 600;
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}
.mobile-nav a:hover { color: var(--text-primary); }
.mobile-overlay {
  position: fixed;
  inset: 0;
  background: oklch(0% 0 0 / 0.6);
  z-index: 998;
  opacity: 0;
  visibility: hidden;
  transition: all var(--transition-base);
}
.mobile-overlay.open { opacity: 1; visibility: visible; }

/* ===== HERO CAROUSEL ===== */
.hero {
  min-height: 100vh;
  display: flex;
  align-items: center;
  position: relative;
  overflow: hidden;
  padding-top: 5rem;
}
.hero-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}
.hero-bg::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 70% 60% at 50% 40%, oklch(65% 0.22 260 / 0.08) 0%, transparent 70%),
              radial-gradient(ellipse 50% 50% at 80% 20%, oklch(72% 0.14 55 / 0.04) 0%, transparent 60%);
}
.hero-grid {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(oklch(100% 0 0 / 0.03) 1px, transparent 1px),
    linear-gradient(90deg, oklch(100% 0 0 / 0.03) 1px, transparent 1px);
  background-size: 80px 80px;
  mask-image: radial-gradient(ellipse 70% 60% at 50% 40%, black 30%, transparent 70%);
}
.hero .container { position: relative; z-index: 1; }
.hero-carousel { position: relative; width: 100%; }
.hero-slides { position: relative; min-height: 420px; }
.hero-slide {
  position: absolute;
  inset: 0;
  opacity: 0;
  transform: translateY(20px);
  transition: all 0.6s cubic-bezier(0.4, 0, 0.2, 1);
  pointer-events: none;
  display: flex;
  flex-direction: column;
  justify-content: center;
  max-width: 800px;
}
.hero-slide.active {
  opacity: 1;
  transform: translateY(0);
  pointer-events: all;
}
.hero-slide-tag {
  display: inline-block;
  padding: 0.35rem 0.85rem;
  border: 1px solid var(--border);
  border-radius: 100px;
  font-size: var(--font-xs);
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: var(--space-md);
  width: fit-content;
}
.hero-slide h2 {
  font-size: var(--font-5xl);
  font-weight: 900;
  line-height: 1.05;
  letter-spacing: -0.03em;
  margin-bottom: var(--space-md);
}
.hero-slide p {
  font-size: var(--font-lg);
  color: var(--text-secondary);
  max-width: 560px;
  line-height: 1.7;
  margin-bottom: var(--space-lg);
}
.hero-controls {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  margin-top: var(--space-xl);
  position: relative;
  z-index: 2;
}
.hero-arrows {
  display: flex;
  gap: 0.5rem;
}
.hero-arrow {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
  color: var(--text-secondary);
}
.hero-arrow:hover { border-color: var(--text-primary); color: var(--text-primary); background: oklch(100% 0 0 / 0.05); }
.hero-arrow svg { width: 20px; height: 20px; }
.hero-dots {
  display: flex;
  gap: 0.5rem;
  margin-left: auto;
}
.hero-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border);
  transition: all var(--transition-base);
}
.hero-dot.active { background: var(--accent); width: 32px; border-radius: 10px; }
.hero-dot:hover { background: var(--text-muted); }

/* ===== TEAM SECTION ===== */
.team { position: relative; }
.team-header { margin-bottom: var(--space-xl); }
.team-tabs {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin-bottom: var(--space-xl);
}
.team-tab {
  padding: 0.65rem 1.5rem;
  border: 1px solid var(--border);
  border-radius: 100px;
  font-size: var(--font-sm);
  font-weight: 600;
  color: var(--text-secondary);
  transition: all var(--transition-base);
}
.team-tab:hover { border-color: var(--text-secondary); color: var(--text-primary); }
.team-tab.active {
  background: var(--text-primary);
  color: var(--bg-primary);
  border-color: var(--text-primary);
}
.team-carousel-wrap {
  position: relative;
  overflow: hidden;
}
.team-cards {
  display: flex;
  gap: var(--space-md);
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
  will-change: transform;
}
.team-card {
  flex: 0 0 calc(33.333% - var(--space-md));
  min-width: calc(33.333% - var(--space-md));
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  display: flex;
  flex-direction: column;
  transition: border-color var(--transition-base);
}
.team-card:hover { border-color: var(--border); }
.team-card-photo {
  width: 100%;
  aspect-ratio: 1;
  border-radius: var(--radius-md);
  background: var(--bg-elevated);
  margin-bottom: var(--space-md);
  overflow: hidden;
  position: relative;
}
.team-card-photo img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: saturate(0.7) contrast(1.05);
}
.team-card-photo-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
  font-weight: 700;
  color: var(--text-muted);
  background: linear-gradient(135deg, var(--bg-elevated), oklch(20% 0.02 260));
}
.team-card-name {
  font-size: var(--font-lg);
  font-weight: 700;
  margin-bottom: 0.25rem;
}
.team-card-title {
  font-size: var(--font-sm);
  color: var(--accent);
  font-weight: 500;
  margin-bottom: 0.25rem;
}
.team-card-office {
  font-size: var(--font-sm);
  color: var(--text-muted);
  margin-bottom: var(--space-md);
}
.team-card-quote {
  font-size: var(--font-sm);
  color: var(--text-secondary);
  line-height: 1.7;
  flex: 1;
  font-style: italic;
  position: relative;
  padding-left: var(--space-md);
  border-left: 2px solid var(--accent);
  margin-bottom: var(--space-md);
}
.team-card-cta {
  font-size: var(--font-xs);
  font-weight: 600;
  color: var(--text-secondary);
  transition: color var(--transition-fast);
  display: flex;
  align-items: center;
  gap: 0.35rem;
}
.team-card-cta:hover { color: var(--text-primary); }
.team-card-cta svg { width: 14px; height: 14px; }
.team-nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  margin-top: var(--space-lg);
}
.team-arrow {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
  color: var(--text-secondary);
}
.team-arrow:hover:not(:disabled) { border-color: var(--text-primary); color: var(--text-primary); }
.team-arrow:disabled { opacity: 0.3; cursor: default; }
.team-arrow svg { width: 18px; height: 18px; }
.team-counter {
  font-size: var(--font-sm);
  color: var(--text-muted);
  font-variant-numeric: tabular-nums;
  min-width: 60px;
  text-align: center;
}

/* ===== WORK SHOWCASE ===== */
.work-header { margin-bottom: var(--space-xl); }
.work-scroll {
  display: flex;
  gap: var(--space-md);
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding-bottom: var(--space-sm);
}
.work-scroll::-webkit-scrollbar { display: none; }
.work-card {
  flex: 0 0 420px;
  scroll-snap-align: start;
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: border-color var(--transition-base);
}
.work-card:hover { border-color: var(--border); }
.work-card-image {
  width: 100%;
  aspect-ratio: 16 / 10;
  background: var(--bg-elevated);
  position: relative;
  overflow: hidden;
}
.work-card-image-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, oklch(20% 0.03 260), oklch(15% 0.02 290));
  position: relative;
}
.work-card-image-placeholder::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 60% 40%, oklch(65% 0.22 260 / 0.15), transparent 70%);
}
.work-card-image-label {
  font-size: var(--font-xs);
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: oklch(80% 0.05 260);
  z-index: 1;
}
.work-card-body { padding: var(--space-lg); }
.work-card-client {
  font-size: var(--font-xs);
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 0.5rem;
}
.work-card-title {
  font-size: var(--font-xl);
  font-weight: 700;
  line-height: 1.3;
  letter-spacing: -0.01em;
  margin-bottom: var(--space-sm);
}
.work-card-quote {
  font-size: var(--font-sm);
  color: var(--text-secondary);
  line-height: 1.7;
  font-style: italic;
}
.work-scroll-hint {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-top: var(--space-md);
  font-size: var(--font-xs);
  color: var(--text-muted);
}
.work-scroll-hint svg { width: 16px; height: 16px; animation: scrollHint 1.5s ease infinite; }
@keyframes scrollHint {
  0%, 100% { transform: translateX(0); }
  50% { transform: translateX(6px); }
}

/* ===== CTA BANNER ===== */
.cta-banner {
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-xl);
  text-align: center;
  padding: var(--space-2xl) var(--space-lg);
  margin: 0 var(--space-lg);
}
.cta-banner h2 {
  font-size: var(--font-3xl);
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-bottom: var(--space-md);
}
.cta-banner p {
  font-size: var(--font-lg);
  color: var(--text-secondary);
  max-width: 640px;
  margin: 0 auto var(--space-lg);
  line-height: 1.7;
}

/* ===== HOW WE WORK ===== */
.hww-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-xl);
  align-items: center;
}
.hww-content h2 {
  font-size: var(--font-4xl);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.02em;
  margin-bottom: var(--space-md);
}
.hww-content p {
  font-size: var(--font-lg);
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: var(--space-lg);
}
.hww-visual {
  aspect-ratio: 4 / 3;
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.hww-visual::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 50%, oklch(65% 0.22 260 / 0.1), transparent 60%);
}
.hww-visual-text {
  font-size: var(--font-sm);
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-muted);
  position: relative;
  z-index: 1;
}

/* ===== INSIGHTS ===== */
.insights-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-md);
}
.insight-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: border-color var(--transition-base);
}
.insight-card:hover { border-color: var(--border); }
.insight-card-thumb {
  aspect-ratio: 16 / 10;
  background: var(--bg-elevated);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.insight-card-thumb::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 50%, oklch(65% 0.22 260 / 0.08), transparent 60%);
}
.insight-card-type {
  font-size: var(--font-xs);
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--accent);
  position: relative;
  z-index: 1;
}
.insight-card-body { padding: var(--space-md); }
.insight-card-title {
  font-size: var(--font-base);
  font-weight: 600;
  line-height: 1.4;
  margin-bottom: var(--space-sm);
}
.insight-card-cta {
  font-size: var(--font-xs);
  font-weight: 600;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  gap: 0.35rem;
  transition: color var(--transition-fast);
}
.insight-card-cta:hover { color: var(--text-primary); }
.insight-card-cta svg { width: 14px; height: 14px; }

/* ===== PRINCIPLES ===== */
.principles-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-md);
}
.principle-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  transition: border-color var(--transition-base);
}
.principle-card:hover { border-color: var(--border); }
.principle-card-number {
  font-size: var(--font-2xl);
  font-weight: 900;
  color: var(--accent);
  opacity: 0.3;
  margin-bottom: var(--space-sm);
  line-height: 1;
}
.principle-card h3 {
  font-size: var(--font-xl);
  font-weight: 700;
  letter-spacing: -0.01em;
  margin-bottom: var(--space-sm);
}
.principle-card p {
  font-size: var(--font-sm);
  color: var(--text-secondary);
  line-height: 1.7;
}

/* ===== FOOTER ===== */
.footer {
  border-top: 1px solid var(--border-light);
  padding: var(--space-2xl) 0 var(--space-lg);
}
.footer-ctas {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-xl);
  padding-bottom: var(--space-2xl);
  border-bottom: 1px solid var(--border-light);
  margin-bottom: var(--space-xl);
}
.footer-cta h3 {
  font-size: var(--font-2xl);
  font-weight: 700;
  letter-spacing: -0.01em;
  margin-bottom: var(--space-md);
}
.footer-cta p {
  font-size: var(--font-base);
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: var(--space-md);
}
.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--space-md);
}
.footer-links {
  display: flex;
  gap: var(--space-lg);
  flex-wrap: wrap;
}
.footer-links a {
  font-size: var(--font-sm);
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}
.footer-links a:hover { color: var(--text-primary); }
.footer-legal {
  font-size: var(--font-xs);
  color: var(--text-muted);
  display: flex;
  gap: var(--space-md);
  flex-wrap: wrap;
}
.footer-legal a { color: var(--text-muted); transition: color var(--transition-fast); }
.footer-legal a:hover { color: var(--text-secondary); }

/* ===== COOKIE BANNER ===== */
.cookie-banner {
  position: fixed;
  bottom: var(--space-md);
  left: 50%;
  transform: translateX(-50%) translateY(120px);
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: var(--space-md) var(--space-lg);
  z-index: 1001;
  max-width: 600px;
  width: calc(100% - 2rem);
  display: flex;
  align-items: center;
  gap: var(--space-md);
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow: 0 20px 60px oklch(0% 0 0 / 0.6);
}
.cookie-banner.visible { transform: translateX(-50%) translateY(0); }
.cookie-banner p {
  font-size: var(--font-sm);
  color: var(--text-secondary);
  line-height: 1.6;
  flex: 1;
}
.cookie-banner p a {
  color: var(--accent);
  text-decoration: underline;
}
.cookie-actions {
  display: flex;
  gap: 0.5rem;
  flex-shrink: 0;
}
.cookie-btn {
  padding: 0.5rem 1rem;
  border-radius: 100px;
  font-size: var(--font-xs);
  font-weight: 600;
  transition: all var(--transition-fast);
  white-space: nowrap;
}
.cookie-btn-accept {
  background: var(--text-primary);
  color: var(--bg-primary);
}
.cookie-btn-accept:hover { background: oklch(88% 0 0); }
.cookie-btn-settings {
  border: 1px solid var(--border);
  color: var(--text-secondary);
}
.cookie-btn-settings:hover { border-color: var(--text-secondary); color: var(--text-primary); }
.cookie-btn-decline {
  color: var(--text-muted);
}
.cookie-btn-decline:hover { color: var(--text-secondary); }

/* ===== RESPONSIVE ===== */
@media (max-width: 1200px) {
  .insights-grid { grid-template-columns: repeat(3, 1fr); }
  .principles-grid { grid-template-columns: repeat(2, 1fr); }
  .team-card { flex: 0 0 calc(50% - var(--space-md)); min-width: calc(50% - var(--space-md)); }
}

@media (max-width: 900px) {
  :root {
    --font-4xl: 2.25rem;
    --font-5xl: 2.75rem;
    --font-6xl: 3.5rem;
    --space-3xl: 5rem;
  }
  .nav-links { display: none; }
  .nav-toggle { display: flex; }
  .hero-slide h2 { font-size: var(--font-4xl); }
  .hww-grid { grid-template-columns: 1fr; }
  .hww-visual { aspect-ratio: 16/9; }
  .insights-grid { grid-template-columns: repeat(2, 1fr); }
  .work-card { flex: 0 0 340px; }
  .footer-ctas { grid-template-columns: 1fr; }
  .cookie-banner { flex-direction: column; text-align: center; }
  .team-card { flex: 0 0 100%; min-width: 100%; }
  .team-tabs { justify-content: center; }
}

@media (max-width: 600px) {
  .container { padding: 0 var(--space-md); }
  :root {
    --font-4xl: 1.75rem;
    --font-5xl: 2.25rem;
    --space-2xl: 3rem;
    --space-3xl: 3.5rem;
  }
