        <h3>Challenge the status quo</h3>
        <p>From launching game-changing products and services to redefining business as usual, our work bridges the gap between what could be and what should be.</p>
      </div>
      <div class="principle-card">
        <div class="principle-card-number">02</div>
        <h3>Fuse art &amp; science to make ideas real</h3>
        <p>We innovate with equal parts expertise in creativity and transformation, leveraging next-level data and tech to elevate experiences for all.</p>
      </div>
      <div class="principle-card">
        <div class="principle-card-number">03</div>
        <h3>Create a lasting impact at global scale</h3>
        <p>Driving meaningful outcomes starts with reimagining systems at a fundamental level. As part of Meridian Consulting, we bring a global reach and diverse skillsets to our approach.</p>
      </div>
      <div class="principle-card">
        <div class="principle-card-number">04</div>
        <h3>Regenerate systems &amp; communities</h3>
        <p>In the eco-digital era, we believe every collaboration is an opportunity to create social, economic and environmental value for all.</p>
      </div>
    </div>
  </div>
</section>

<!-- ===== FOOTER ===== -->
<footer class="footer" id="careers">
  <div class="container">
    <div class="footer-ctas">
      <div class="footer-cta">
        <h3>Ready to make your mark?</h3>
        <p>As your reinvention and experience partner, our global team is here to help.</p>
        <a href="#" class="btn btn-outline">Get in touch</a>
      </div>
      <div class="footer-cta">
        <h3>Do your best work among a caring community of diverse talents.</h3>
        <a href="#" class="btn btn-outline">Join our team</a>
      </div>
    </div>
    <div class="footer-bottom">
      <div class="footer-links">
        <a href="#">Studios</a>
        <a href="#">Culture</a>
        <a href="#">DE&amp;I</a>
        <a href="#">Play</a>
      </div>
      <div class="footer-legal">
        <span>&copy; 2026 Leap Studio, part of Meridian Consulting Group</span>
        <a href="#">Privacy Policy</a>
        <a href="#">Terms of Use</a>
        <a href="#">Cookie Policy</a>
        <a href="#">Cookie Settings</a>
      </div>
    </div>
  </div>
</footer>

<!-- ===== COOKIE BANNER ===== -->
<div class="cookie-banner" id="cookieBanner">
  <p>We use cookies to enhance your experience. By continuing, you agree to our use of cookies. <a href="#">Learn more</a></p>
  <div class="cookie-actions">
    <button class="cookie-btn cookie-btn-accept" id="cookieAccept">Accept All</button>
    <button class="cookie-btn cookie-btn-settings" id="cookieSettings">Manage</button>
    <button class="cookie-btn cookie-btn-decline" id="cookieDecline">Decline</button>
  </div>
</div>

<script>
/* ===== TEAM DATA ===== */
const teamData = {
  'north-america': [
    {
      name: 'Denice Alvarez',
      title: 'Office Manager',
      office: 'New York',
      quote: 'As the Office Manager, I engage with teams from every discipline, and have learned so much through my day-to-day interactions with my fellow leapers.',
      initials: 'DA'
    },
    {
      name: 'Marco Bellini',
      title: 'Design Director',
      office: 'San Francisco',
      quote: 'Every day we are delighted by the immense beauty that nature holds. When engaged in the act of creation, it is our responsibility to channel that delight into the things we make.',
      initials: 'MB'
    }
  ],
  'asia': [
    {
      name: 'Priya Mehta',
      title: 'Studio Head',
      office: 'Bangalore',
      quote: 'We bring your brand vision to life, with transformative ideas and impactful marketing campaigns fueled by creativity and enthusiasm.',
      initials: 'PM'
    },
    {
      name: 'Thierry Lam',
      title: 'Design Lead',
      office: 'Singapore',
      quote: 'Good design is multifaceted. It impacts functionality, aesthetics, strategy, environment, business and so much more. Great design is seamless.',
      initials: 'TL'
    }
  ],
  'europe': [
    {
      name: 'Gavin Hartley',
      title: 'Managing Director',
      office: 'London',
      quote: "It's my job to make sure we innovate and push the boundaries when collaborating with brands to create inspiring customer experiences that deliver great business results.",
      initials: 'GH'
    },
    {
      name: 'Francesca Terzi',
      title: 'Design Director',
      office: 'Munich',
      quote: 'At Leap Studio, I am constantly amazed by the talent I am surrounded with. We love to dream big and bring those dreams to life.',
      initials: 'FT'
    }
  ],
  'oceania': [
    {
      name: 'Jacintha Soo Ho',
      title: 'Senior Manager, CX Transformation',
      office: 'Melbourne',
      quote: 'I love helping clients see beyond their assumptions and showing them opportunities they have not thought of before.',
      initials: 'JS'
    }
  ]
};

/* ===== STATE ===== */
let currentRegion = 'north-america';
let teamIndex = 0;
let heroIndex = 0;
let heroInterval;

/* ===== HERO CAROUSEL ===== */
const heroSlides = document.querySelectorAll('.hero-slide');
const heroDotsContainer = document.getElementById('heroDots');
const totalHeroSlides = heroSlides.length;

// Create dots
for (let i = 0; i < totalHeroSlides; i++) {
  const dot = document.createElement('button');
  dot.className = 'hero-dot' + (i === 0 ? ' active' : '');
  dot.setAttribute('aria-label', 'Go to slide ' + (i + 1));
  dot.addEventListener('click', () => goToHeroSlide(i));
  heroDotsContainer.appendChild(dot);
}

const heroDots = document.querySelectorAll('.hero-dot');

function goToHeroSlide(index) {
  heroSlides[heroIndex].classList.remove('active');
  heroDots[heroIndex].classList.remove('active');
  heroIndex = index;
  heroSlides[heroIndex].classList.add('active');
  heroDots[heroIndex].classList.add('active');
}

function nextHeroSlide() { goToHeroSlide((heroIndex + 1) % totalHeroSlides); }
function prevHeroSlide() { goToHeroSlide((heroIndex - 1 + totalHeroSlides) % totalHeroSlides); }

document.getElementById('heroNext').addEventListener('click', () => { nextHeroSlide(); resetHeroAutoplay(); });
document.getElementById('heroPrev').addEventListener('click', () => { prevHeroSlide(); resetHeroAutoplay(); });

function startHeroAutoplay() {
  heroInterval = setInterval(nextHeroSlide, 5000);
}

function resetHeroAutoplay() {
  clearInterval(heroInterval);
  startHeroAutoplay();
}

startHeroAutoplay();

// Swipe support for hero
let heroTouchStartX = 0;
const heroEl = document.getElementById('heroCarousel');
heroEl.addEventListener('touchstart', (e) => { heroTouchStartX = e.touches[0].clientX; });
heroEl.addEventListener('touchend', (e) => {
  const diff = heroTouchStartX - e.changedTouches[0].clientX;
  if (Math.abs(diff) > 50) {
    if (diff > 0) nextHeroSlide();
    else prevHeroSlide();
    resetHeroAutoplay();
  }
});

/* ===== TEAM REGION TOGGLE + CAROUSEL ===== */
const teamCardsContainer = document.getElementById('teamCards');
const teamCounter = document.getElementById('teamCounter');
const teamPrevBtn = document.getElementById('teamPrev');
const teamNextBtn = document.getElementById('teamNext');

function renderTeamCards() {
  const members = teamData[currentRegion];
  teamCardsContainer.innerHTML = members.map((m, i) => `
    <div class="team-card" data-team-index="${i}">
      <div class="team-card-photo">
        <div class="team-card-photo-placeholder">${m.initials}</div>
      </div>
      <div class="team-card-name">${m.name}</div>
      <div class="team-card-title">${m.title}</div>
      <div class="team-card-office">${m.office}</div>
      <blockquote class="team-card-quote">${m.quote}</blockquote>
      <a href="#" class="team-card-cta">
        Contact Leap Studio ${m.office}
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M5 12h14M12 5l7 7-7 7"/></svg>
      </a>
    </div>
  `).join('');
  teamIndex = 0;
  updateTeamCarousel();
}

function updateTeamCarousel() {
  const members = teamData[currentRegion];
  const cardWidth = teamCardsContainer.querySelector('.team-card')?.offsetWidth || 0;
  const gap = 24; // var(--space-md)
  const offset = teamIndex * (cardWidth + gap);
  teamCardsContainer.style.transform = `translateX(-${offset}px)`;
  teamCounter.textContent = `${teamIndex + 1} / ${members.length}`;
  teamPrevBtn.disabled = teamIndex === 0;
  teamNextBtn.disabled = teamIndex >= members.length - 1;
}

// Region tab clicks
document.getElementById('teamTabs').addEventListener('click', (e) => {
  const tab = e.target.closest('.team-tab');
  if (!tab) return;
  document.querySelectorAll('.team-tab').forEach(t => t.classList.remove('active'));
  tab.classList.add('active');
  currentRegion = tab.dataset.region;
  renderTeamCards();
});

// Team navigation
teamPrevBtn.addEventListener('click', () => {
  if (teamIndex > 0) { teamIndex--; updateTeamCarousel(); }
});
teamNextBtn.addEventListener('click', () => {
  if (teamIndex < teamData[currentRegion].length - 1) { teamIndex++; updateTeamCarousel(); }
});

// Swipe support for team carousel
let teamTouchStartX = 0;
const teamWrap = document.getElementById('teamCarouselWrap');
teamWrap.addEventListener('touchstart', (e) => { teamTouchStartX = e.touches[0].clientX; });
teamWrap.addEventListener('touchend', (e) => {
  const diff = teamTouchStartX - e.changedTouches[0].clientX;
  if (Math.abs(diff) > 50) {
    if (diff > 0 && teamIndex < teamData[currentRegion].length - 1) { teamIndex++; }
    else if (diff < 0 && teamIndex > 0) { teamIndex--; }
    updateTeamCarousel();
  }
});

// Handle resize for team carousel
window.addEventListener('resize', updateTeamCarousel);

// Initial render
renderTeamCards();

/* ===== LANGUAGE SELECTOR ===== */
const langToggle = document.getElementById('langToggle');
const langDropdown = document.getElementById('langDropdown');
const langSelector = document.getElementById('langSelector');

langToggle.addEventListener('click', (e) => {
  e.stopPropagation();
  const isOpen = langDropdown.classList.contains('open');
  langDropdown.classList.toggle('open');
  langToggle.setAttribute('aria-expanded', !isOpen);
});

langDropdown.addEventListener('click', (e) => {
  const btn = e.target.closest('button');
  if (!btn) return;
  langDropdown.querySelectorAll('button').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  langToggle.childNodes[1].textContent = btn.textContent;
  langDropdown.classList.remove('open');
  langToggle.setAttribute('aria-expanded', 'false');
});

document.addEventListener('click', (e) => {
  if (!langSelector.contains(e.target)) {
    langDropdown.classList.remove('open');
    langToggle.setAttribute('aria-expanded', 'false');
  }
});

/* ===== MOBILE NAVIGATION ===== */
const navToggle = document.getElementById('navToggle');
const mobileNav = document.getElementById('mobileNav');
const mobileOverlay = document.getElementById('mobileOverlay');

function openMobileNav() {
  navToggle.classList.add('open');
  mobileNav.classList.add('open');
  mobileOverlay.classList.add('open');
  document.body.style.overflow = 'hidden';
}

function closeMobileNav() {
  navToggle.classList.remove('open');
  mobileNav.classList.remove('open');
  mobileOverlay.classList.remove('open');
  document.body.style.overflow = '';
}

navToggle.addEventListener('click', () => {
  if (navToggle.classList.contains('open')) closeMobileNav();
  else openMobileNav();
});

mobileOverlay.addEventListener('click', closeMobileNav);
mobileNav.querySelectorAll('a').forEach(link => {
  link.addEventListener('click', closeMobileNav);
});

/* ===== SCROLL EFFECTS ===== */
const nav = document.getElementById('nav');
function updateNavOnScroll() {
  if (window.scrollY > 50) nav.classList.add('scrolled');
  else nav.classList.remove('scrolled');
}
window.addEventListener('scroll', updateNavOnScroll, { passive: true });

/* ===== COOKIE CONSENT ===== */
const cookieBanner = document.getElementById('cookieBanner');

function showCookieBanner() {
  if (!localStorage.getItem('cookieConsent')) {
    setTimeout(() => cookieBanner.classList.add('visible'), 800);
  }
}

function hideCookieBanner() {
  cookieBanner.classList.remove('visible');
}

document.getElementById('cookieAccept').addEventListener('click', () => {
  localStorage.setItem('cookieConsent', 'accepted');
  hideCookieBanner();
});

document.getElementById('cookieDecline').addEventListener('click', () => {
  localStorage.setItem('cookieConsent', 'declined');
  hideCookieBanner();
});

document.getElementById('cookieSettings').addEventListener('click', () => {
  // In a real app, this opens a detailed settings panel
  localStorage.setItem('cookieConsent', 'custom');
  hideCookieBanner();
});

showCookieBanner();

/* ===== SMOOTH SCROLL FOR NAV LINKS ===== */
document.querySelectorAll('a[href^="#"]').forEach(anchor => {
  anchor.addEventListener('click', function(e) {
    const target = document.querySelector(this.getAttribute('href'));
    if (target) {
      e.preventDefault();
      const navHeight = nav.offsetHeight;
      const targetPosition = target.getBoundingClientRect().top + window.pageYOffset - navHeight - 20;
      window.scrollTo({ top: targetPosition, behavior: 'smooth' });
    }
  });
});
</script>
</body>
</html>
